INSERT INTO "storage" VALUES('potato-whole','potato','whole','빛을 차단하고 통풍되는 곳에 둔다. 원문은 7~10℃에서 몇 주라고 설명한다.',NULL,NULL,NULL,NULL,NULL,NULL,'98666','verified');
INSERT INTO "storage" VALUES('onion-whole','onion','whole','종이봉투나 망에 넣고 건조하며 통풍되는 곳에 보관한다. 원문 온도는 15~25℃다.',NULL,NULL,NULL,NULL,NULL,NULL,'98665','verified');
