INSERT INTO "storage" VALUES('bell-pepper-whole','bell-pepper','whole','원문 조건 8~10℃에서 3~4주, 습도 90~95%. 일반 가정 냉장고의 소비기한으로 사용하지 않는다.',8.0,10.0,3.0,4.0,'week','90~95%','pepper101924','verified');
INSERT INTO "vegetables" VALUES('potato','감자','Solanum tuberosum','전분이 있는 덩이줄기. 삶기·조림·옹심이에 활용한다.','씻어 껍질을 손질한다. 껍질을 벗긴 뒤 물에 담가 갈변을 줄일 수 있다.','98666','partial','곰팡이·부패·심한 물러짐·원인 불명의 변색·깊은 손상은 외형 등급 대상에서 제외한다.','editorial_conservative_rule');
INSERT INTO "vegetables" VALUES('carrot','당근','Daucus carota','뿌리를 먹는 채소. 샐러드·카레 재료로 활용한다.',NULL,'carrot101944','partial','곰팡이·부패·심한 물러짐·원인 불명의 변색·깊은 손상은 외형 등급 대상에서 제외한다.','editorial_conservative_rule');
INSERT INTO "vegetables" VALUES('onion','양파','Allium cepa','생으로는 매운 향이 있으며 가열하면 부드러워진다. 볶음·샐러드·양념에 쓴다.','뿌리와 마른 껍질을 제거하고 용도에 맞게 썬다.','98665','partial','곰팡이·부패·심한 물러짐·원인 불명의 변색·깊은 손상은 외형 등급 대상에서 제외한다.','editorial_conservative_rule');
INSERT INTO "vegetables" VALUES('aehobak','애호박',NULL,'덜 자란 열매를 먹는 국내 애호박. 볶음·전·찌개에 사용한다. 주키니와 별도 재료로 관리한다.','씻고 꼭지를 제거한 뒤 조리 방법에 맞춰 자른다.','208634','partial','곰팡이·부패·심한 물러짐·원인 불명의 변색·깊은 손상은 외형 등급 대상에서 제외한다.','editorial_conservative_rule');
INSERT INTO "vegetables" VALUES('eggplant','가지','Solanum melongena','담백하고 익히면 부드러운 식감. 구이·볶음·조림·나물로 사용한다.','흐르는 물로 세척한다.','206741','partial','곰팡이·부패·심한 물러짐·원인 불명의 변색·깊은 손상은 외형 등급 대상에서 제외한다.','editorial_conservative_rule');
INSERT INTO "vegetables" VALUES('bell-pepper','파프리카',NULL,'착색 단고추. 빨강·노랑·주황·녹색의 영양값을 합치지 않는다.',NULL,'pepper101924','partial','곰팡이·부패·심한 물러짐·원인 불명의 변색·깊은 손상은 외형 등급 대상에서 제외한다.','editorial_conservative_rule');
